// LeaderboardEntry represents a run in a metric leaderboard.
type LeaderboardEntry struct {
\tRank       int                `json:"rank"`
\tRunID      string             `json:"run_id"`
\tValue      float64            `json:"value"`
\tParameters map[string]float64 `json:"parameters"`
\tMetrics    map[string]float64 `json:"metrics"`
}

// LeaderboardResult contains the top runs for a metric.
type LeaderboardResult struct {
\tExperiment string             `json:"experiment"`
\tMetric     string             `json:"metric"`
\tOrder      string             `json:"order"`
\tEntries    []LeaderboardEntry `json:"entries"`
\tTotalRuns  int                `json:"total_runs"`
}

// Leaderboard returns the top runs for an experiment ranked by a metric.
func (t *Tracker) Leaderboard(experimentName, metric, order string, limit int) (*LeaderboardResult, error) {
\tif order == "" {
\t\torder = "desc"
\t}
\tif order != "asc" && order != "desc" {
\t\treturn nil, fmt.Errorf("order must be \\"asc\\" or \\"desc\\"")
\t}

\tt.mu.RLock()
\tdefer t.mu.RUnlock()

\texp, exists := t.experiments[experimentName]
\tif !exists {
\t\treturn nil, fmt.Errorf("experiment %q not found", experimentName)
\t}

\ttype candidate struct {
\t\trun   *Run
\t\tvalue float64
\t}
\tvar candidates []candidate
\tfor _, run := range exp.Runs {
\t\tif run == nil {
\t\t\tcontinue
\t\t}
\t\tvalue, ok := run.Metrics[metric]
\t\tif !ok {
\t\t\tcontinue
\t\t}
\t\tcandidates = append(candidates, candidate{run: run, value: value})
\t}

\tsort.Slice(candidates, func(i, j int) bool {
\t\tif candidates[i].value != candidates[j].value {
\t\t\tif order == "desc" {
\t\t\t\treturn candidates[i].value > candidates[j].value
\t\t\t}
\t\t\treturn candidates[i].value < candidates[j].value
\t\t}
\t\treturn candidates[i].run.ID < candidates[j].run.ID
\t})

\tif limit < 0 {
\t\tlimit = 0
\t}
\tif limit > len(candidates) {
\t\tlimit = len(candidates)
\t}

\tentries := make([]LeaderboardEntry, 0, limit)
\tfor i := 0; i < limit; i++ {
\t\trun := candidates[i].run
\t\tentries = append(entries, LeaderboardEntry{
\t\t\tRank:       i + 1,
\t\t\tRunID:      run.ID,
\t\t\tValue:      candidates[i].value,
\t\t\tParameters: run.Parameters,
\t\t\tMetrics:    run.Metrics,
\t\t})
\t}

\treturn &LeaderboardResult{
\t\tExperiment: experimentName,
\t\tMetric:     metric,
\t\tOrder:      order,
\t\tEntries:    entries,
\t\tTotalRuns:  len(candidates),
\t}, nil
}

// SummaryResult contains basic statistics for a metric across runs.
type SummaryResult struct {
\tExperiment string  `json:"experiment"`
\tMetric     string  `json:"metric"`
\tCount      int     `json:"count"`
\tMin        float64 `json:"min"`
\tMax        float64 `json:"max"`
\tMean       float64 `json:"mean"`
\tMedian     float64 `json:"median"`
}

// Summary computes summary statistics for a metric across all runs in an experiment.
func (t *Tracker) Summary(experimentName, metric string) (*SummaryResult, error) {
\tt.mu.RLock()
\tdefer t.mu.RUnlock()

\texp, exists := t.experiments[experimentName]
\tif !exists {
\t\treturn nil, fmt.Errorf("experiment %q not found", experimentName)
\t}

\tvar values []float64
\tfor _, run := range exp.Runs {
\t\tif run == nil {
\t\t\tcontinue
\t\t}
\t\tif value, ok := run.Metrics[metric]; ok {
\t\t\tvalues = append(values, value)
\t\t}
\t}

\tif len(values) == 0 {
\t\treturn nil, fmt.Errorf("no runs have metric %q", metric)
\t}

\tsort.Float64s(values)

\tmin := values[0]
\tmax := values[len(values)-1]
\tsum := 0.0
\tfor _, v := range values {
\t\tsum += v
\t}
\tmean := sum / float64(len(values))

\tmedian := 0.0
\tn := len(values)
\tif n%2 == 1 {
\t\tmedian = values[n/2]
\t} else {
\t\tmedian = (values[n/2-1] + values[n/2]) / 2.0
\t}

\treturn &SummaryResult{
\t\tExperiment: experimentName,
\t\tMetric:     metric,
\t\tCount:      n,
\t\tMin:        min,
\t\tMax:        max,
\t\tMean:       mean,
\t\tMedian:     median,
\t}, nil
}'''
